WITH matched_keys AS (SELECT id, customer_id FROM accounts EXCEPT DISTINCT SELECT id, customer_id FROM accounts WHERE status = 'OPEN'), verified AS (SELECT s.* FROM accounts s JOIN matched_keys k ON s.id = k.id AND s.customer_id = k.customer_id) SELECT DATE_TRUNC('QUARTER', opened_date) AS quarter_start, CASE WHEN balance >= 62000 THEN 'HIGH' ELSE 'LOW' END AS balance_tier, account_type, COUNT(*) AS cnt, PERCENTILE_APPROX(balance, ARRAY(0.25, 0.5, 0.75)) AS balance_quartiles, DENSE_RANK() OVER (PARTITION BY DATE_TRUNC('QUARTER', opened_date) ORDER BY COUNT(*) DESC) AS cnt_dense_rank FROM verified GROUP BY 1, 2, 3;
